{
  "title": "rescue_in_the_ruined_city",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The heroes arrive at the ruined gate.",
      "visual_description": "A massive stone gate, cracked and overgrown with thorny vines, stands before the ruined city. Two armored figures, one holding a map, peer through the arch into mist.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople flee through a market square.",
      "visual_description": "A cobblestone market square littered with broken stalls. Frightened townspeople scramble away clutching baskets and children, while red royal banners hang torn from a balcony.",
      "characters": ["townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "The map reader spots a cursed tower.",
      "visual_description": "The map reader points toward a spiraling black tower with glowing windows. The scout crouches beside him, scanning the sky for movement.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 4,
      "caption": "A magic helper tests a sealed door.",
      "visual_description": "A hooded magic helper presses both palms against a large stone door etched with glowing runes. The door shudders but does not open.",
      "characters": ["magic_helper"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march through an archway.",
      "visual_description": "A line of helmeted soldiers in dark armor marches beneath a crumbling arch. Their spears glint in the fading light.",
      "characters": ["armored_patrol"]
    },
    {
      "scene_number": 6,
      "caption": "The comic-relief official yawns on a wall.",
      "visual_description": "A sleepy official in rumpled robes sits on a broken wall, yawning as he holds a lantern that has gone out. Banners flutter behind him.",
      "characters": ["sleepy_official"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon circulate in an alley.",
      "visual_description": "Two townspeople whisper in a narrow alley, one gesturing upward at claw marks gouged into the stone above.",
      "characters": ["townspeople"]
    },
    {
      "scene_number": 8,
      "caption": "The scout crosses a rope bridge between towers.",
      "visual_description": "The scout balances on a fraying rope bridge stretching between two ruined towers. Wind tugs at his cloak as he looks down at a chasm.",
      "characters": ["scout"]
    },
    {
      "scene_number": 9,
      "caption": "The magic helper opens a mirror portal.",
      "visual_description": "The magic helper waves a hand before a tall mirror, and the glass ripples like water. The map reader and scout watch from behind.",
      "characters": ["magic_helper", "map_reader", "scout"]
    },
    {
      "scene_number": 10,
      "caption": "The party enters a hall of old banners.",
      "visual_description": "A long hall lined with faded banners bearing a crest of a lion and crescent. Dust motes float in shafts of light from a broken ceiling.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door glows with shifting symbols.",
      "visual_description": "A large oval door of black stone covered in symbols that shift and glow in sequence. The magic helper studies it while the others stand ready.",
      "characters": ["magic_helper", "map_reader", "scout"]
    },
    {
      "scene_number": 12,
      "caption": "The sleepy official stumbles into a trap.",
      "visual_description": "The official trips over a tripwire, and a net of chains drops from the ceiling. He looks up in alarm, lantern rolling away.",
      "characters": ["sleepy_official"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols surround the tower base.",
      "visual_description": "Soldiers form a circle around the base of the cursed tower, torches lit, shields locked. The tower's shadow falls across them.",
      "characters": ["armored_patrol"]
    },
    {
      "scene_number": 14,
      "caption": "The scout retrieves a key from a gargoyle.",
      "visual_description": "The scout reaches into the open mouth of a stone gargoyle perched on a tower ledge, pulling out a brass key.",
      "characters": ["scout"]
    },
    {
      "scene_number": 15,
      "caption": "The magic helper dispels the curse on the tower door.",
      "visual_description": "The magic helper stands before a door wreathed in black smoke, hands glowing with white light as the smoke peels away.",
      "characters": ["magic_helper"]
    },
    {
      "scene_number": 16,
      "caption": "The rescued character appears on the tower stairs.",
      "visual_description": "A figure in torn clothes emerges from the now-open tower door, blinking in the light. The map reader and scout rush forward.",
      "characters": ["map_reader", "scout", "rescued_character"]
    },
    {
      "scene_number": 17,
      "caption": "The party flees across the bridge controls.",
      "visual_description": "The group runs across a stone platform where a large wheel controls a drawbridge. The sleepy official is being pulled along by the scout.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "rescued_character"]
    },
    {
      "scene_number": 18,
      "caption": "Escape across the crumbling bridge.",
      "visual_description": "The entire party races across a narrow stone bridge with broken balustrades. Behind them, the city towers are silhouetted against a red sunset. The bridge begins to crumble at the far end.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official", "rescued_character", "armored_patrol"]
    }
  ]
}

